115→func (c *Claude) RunPrompt(ctx context.Context, dir string, prompt string, opts ...Option) (Output, error) {
116→	cfg := &runConfig{Model: "haiku"}
117→	for _, o := range opts {
118→		o(cfg)
119→	}
120→
121→	configDir, err := isolatedConfigDir()
122→	if err != nil {
123→		return Output{}, fmt.Errorf("create isolated config dir: %w", err)
124→	}
125→	defer os.RemoveAll(configDir)
126→
127→	args := []string{"-p", prompt, "--model", cfg.Model, "--dangerously-skip-permissions"}
128→	displayArgs := []string{"-p", fmt.Sprintf("%q", prompt), "--model", cfg.Model, "--dangerously-skip-permissions"}
129→	cmd := exec.CommandContext(ctx, "claude", args...)
130→	cmd.Dir = dir
131→	cmd.Stdin = nil
132→	cmd.Env = append(cleanEnv(), "ACCESSIBLE=1", "ENTIRE_TEST_TTY=0", "CLAUDE_CONFIG_DIR="+configDir)
133→	cmd.SysProcAttr = &syscall.SysProcAttr{Setpgid: true}
134→	cmd.Cancel = func() error {
135→		return syscall.Kill(-cmd.Process.Pid, syscall.SIGKILL)
136→	}
137→	cmd.WaitDelay = 5 * time.Second
138→
139→	var stdout, stderr strings.Builder
140→	cmd.Stdout = &stdout
141→	cmd.Stderr = &stderr
142→
143→	err = cmd.Run()
144→	exitCode := 0
145→	exitErr := &exec.ExitError{}
146→	if errors.As(err, &exitErr) {
147→		exitCode = exitErr.ExitCode()
148→	}
149→
150→	return Output{
151→		Command:  "claude " + strings.Join(displayArgs, " "),
152→		Stdout:   stdout.String(),
153→		Stderr:   stderr.String(),
154→		ExitCode: exitCode,
155→	}, err
156→}
