 3→import (
 4→	"context"
 5→	"time"
 6→)
 7→
 8→type Output struct {
 9→	Command  string
10→	Stdout   string
11→	Stderr   string
12→	ExitCode int
13→}
14→
15→type Option func(*runConfig)
16→type runConfig struct {
17→	Model          string
18→	PermissionMode string
19→}
20→
21→func WithModel(model string) Option {
22→	return func(c *runConfig) { c.Model = model }
23→}
24→
25→func WithPermissionMode(mode string) Option {
26→	return func(c *runConfig) { c.PermissionMode = mode }
27→}
28→
29→type Agent interface {
30→	Name() string
31→	EntireAgent() string
32→	PromptPattern() string
33→	// TimeoutMultiplier returns a factor applied to per-test timeouts.
34→	// Slower agents (e.g. Gemini) return values > 1.
35→	TimeoutMultiplier() float64
36→	RunPrompt(ctx context.Context, dir string, prompt string, opts ...Option) (Output, error)
37→	StartSession(ctx context.Context, dir string) (Session, error)
38→	// Bootstrap performs one-time CI setup (auth config, warmup, etc.).
39→	// Called before any tests run. Implementations should be idempotent.
40→	Bootstrap() error
41→	// IsTransientError returns true if the error from RunPrompt looks like
42→	// a transient API failure (e.g. 500, rate limit, network error) that
43→	// is worth retrying.
44→	IsTransientError(out Output, err error) bool
45→}
46→
47→type Session interface {
48→	Send(input string) error
49→	WaitFor(pattern string, timeout time.Duration) (string, error)
50→	Capture() string
51→	Close() error
52→}
53→
54→var registry []Agent
55→var gates = map[string]chan struct{}{}
56→
57→func Register(a Agent) {
58→	registry = append(registry, a)
59→}
60→
61→// RegisterGate sets a concurrency limit for an agent's tests.
62→// Tests call AcquireSlot/ReleaseSlot to respect this limit.
63→func RegisterGate(name string, max int) {
64→	gates[name] = make(chan struct{}, max)
65→}
66→
67→// AcquireSlot blocks until a test slot is available for the agent or the
68→// context is cancelled. Returns a non-nil error if the context expires
69→// before a slot opens.
70→func AcquireSlot(ctx context.Context, a Agent) error {
71→	g, ok := gates[a.Name()]
72→	if !ok {
73→		return nil
74→	}
75→	select {
76→	case g <- struct{}{}:
77→		return nil
78→	case <-ctx.Done():
79→		return ctx.Err()
80→	}
81→}
82→
83→// ReleaseSlot frees a test slot for the agent.
84→func ReleaseSlot(a Agent) {
85→	if g, ok := gates[a.Name()]; ok {
86→		<-g
87→	}
88→}
89→
90→func All() []Agent {
91→	return registry
92→}
