172→func (c *Claude) StartSession(ctx context.Context, dir string) (Session, error) {
173→	name := fmt.Sprintf("claude-test-%d", time.Now().UnixNano())
174→
175→	envArgs := []string{"ACCESSIBLE=1", "ENTIRE_TEST_TTY=0"}
176→
177→	// On CI (no macOS Keychain), use an isolated config dir so Claude Code
178→	// picks up ANTHROPIC_API_KEY from the environment instead of trying OAuth.
179→	// Locally, we skip CLAUDE_CONFIG_DIR so the Keychain-based auth works.
180→	if os.Getenv("CI") != "" {
181→		configDir, err := isolatedConfigDir()
182→		if err == nil {
183→			envArgs = append(envArgs, "CLAUDE_CONFIG_DIR="+configDir)
184→			fmt.Fprintf(os.Stderr, "[e2e] claude StartSession: CI mode, using isolated config dir %s\n", configDir)
185→		}
186→	} else {
187→		fmt.Fprintf(os.Stderr, "[e2e] claude StartSession: local mode, using default Keychain auth (no CLAUDE_CONFIG_DIR)\n")
188→	}
189→
190→	args := append([]string{"env"}, envArgs...)
191→	args = append(args, "claude", "--dangerously-skip-permissions")
192→	s, err := NewTmuxSession(name, dir, []string{"CLAUDECODE"}, args[0], args[1:]...)
193→	if err != nil {
194→		return nil, err
195→	}
196→
197→	// Dismiss startup dialogs until we reach the input prompt.
198→	for range 5 {
199→		content, err := s.WaitFor(`❯`, 15*time.Second)
200→		if err != nil {
201→			_ = s.Close()
202→			return nil, fmt.Errorf("waiting for startup prompt: %w", err)
203→		}
204→		if !strings.Contains(content, "Enter to confirm") {
205→			break
206→		}
207→		// The bypass permissions dialog defaults to "No, exit" —
208→		// arrow down to "Yes, I accept" before confirming.
209→		if strings.Contains(content, "Yes, I accept") {
210→			_ = s.SendKeys("Down")
211→			time.Sleep(200 * time.Millisecond)
212→		}
213→		_ = s.SendKeys("Enter")
214→		time.Sleep(500 * time.Millisecond)
215→	}
216→	s.stableAtSend = ""
217→
218→	return s, nil
219→}
